-- Username + password accounts with a mascot, and sessions (ADR 0011).
-- The key-based accounts of migration 1 only ever held test accounts, so the table is
-- replaced instead of migrated (expand/contract was not needed before launch).
DROP TABLE accounts;

CREATE TABLE accounts (
    -- UUIDv7, generated by the application.
    id            BLOB    NOT NULL PRIMARY KEY
                  CONSTRAINT check_accounts_id_length CHECK (length(id) = 16),
    -- Mirrors `Username`: 3–20 chars, stored lowercase. Also the room's name.
    username      TEXT    NOT NULL
                  CONSTRAINT uq_accounts_username UNIQUE
                  CONSTRAINT check_accounts_username_format
                      CHECK (length(username) BETWEEN 3 AND 20 AND username = lower(username)),
    -- Argon2id PHC string; the password itself is never stored.
    password_hash TEXT    NOT NULL
                  CONSTRAINT check_accounts_password_hash_format
                      CHECK (substr(password_hash, 1, 10) = '$argon2id$'),
    -- Mirrors `Mascot`.
    mascot        TEXT    NOT NULL
                  CONSTRAINT check_accounts_mascot_known CHECK (mascot IN (
                      'alien', 'astronaut', 'cybercat', 'dragon', 'gamer', 'ghost',
                      'knight', 'ninja', 'pirate', 'robot', 'slime', 'wizard')),
    -- Unix milliseconds, UTC; the time encoded in `id`.
    created_at    INTEGER NOT NULL
                  CONSTRAINT check_accounts_created_at_positive CHECK (created_at > 0)
) STRICT;

CREATE TABLE sessions (
    id         BLOB    NOT NULL PRIMARY KEY
               CONSTRAINT check_sessions_id_length CHECK (length(id) = 16),
    account_id BLOB    NOT NULL
               CONSTRAINT fk_sessions_account_id_accounts
                   REFERENCES accounts (id) ON DELETE CASCADE,
    -- SHA-256 of the session token (a 128-bit random bearer secret).
    token_hash BLOB    NOT NULL
               CONSTRAINT uq_sessions_token_hash UNIQUE
               CONSTRAINT check_sessions_token_hash_length CHECK (length(token_hash) = 32),
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL
               CONSTRAINT check_sessions_expires_at_after_created_at
                   CHECK (expires_at > created_at)
) STRICT;

-- Foreign key column (rule 10) and the expired-session purge.
CREATE INDEX index_sessions_on_account_id ON sessions (account_id);
CREATE INDEX index_sessions_on_expires_at ON sessions (expires_at);
